INSERT INTO `module_settings` (`id`, `tenant_id`, `module`, `setting_group`, `setting_key`, `setting_value`, `default_value`, `value_type`, `validation_rules`, `description`, `sort_order`, `is_system`, `is_editable`, `created_at`, `updated_at`) VALUES
(1, 1, 'finance', 'chart_of_accounts', 'account_numbering_enabled', '1', '1', 'BOOLEAN', NULL, 'Automatically suggest the next available account code when creating an account.', 10, 0, 1, '2026-08-08 11:24:07', '2026-08-08 14:51:24'),
(2, 1, 'finance', 'chart_of_accounts', 'allow_manual_account_codes', '1', '1', 'BOOLEAN', NULL, 'Allow administrators to manually enter an account code.', 20, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(3, 1, 'finance', 'chart_of_accounts', 'account_code_increment', '10', '10', 'INTEGER', '{\"min\":1,\"max\":1000}', 'Default increment used when suggesting the next account code.', 30, 0, 1, '2026-08-08 11:24:07', '2026-08-08 14:51:24'),
(4, 1, 'finance', 'chart_of_accounts', 'account_code_padding', '5', '4', 'INTEGER', '{\"min\":1,\"max\":10}', 'Number of digits used when formatting automatically suggested account codes.', 40, 0, 1, '2026-08-08 11:24:07', '2026-08-08 16:12:20'),
(5, 1, 'finance', 'chart_of_accounts', 'inherit_account_type', '1', '1', 'BOOLEAN', NULL, 'Automatically inherit the parent account type when creating a child account.', 50, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(6, 1, 'finance', 'chart_of_accounts', 'inherit_normal_balance', '1', '1', 'BOOLEAN', NULL, 'Automatically inherit the parent account normal balance when creating a child account.', 60, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(7, 1, 'finance', 'chart_of_accounts', 'suggest_child_account_code', '1', '1', 'BOOLEAN', NULL, 'Automatically suggest an unused account code for child accounts.', 70, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(8, 1, 'finance', 'chart_of_accounts', 'protect_system_accounts', '1', '1', 'BOOLEAN', NULL, 'Prevent system-generated accounts from being deleted.', 80, 1, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(9, 1, 'finance', 'chart_of_accounts', 'allow_account_deletion', '1', '1', 'BOOLEAN', NULL, 'Allow administrators to delete eligible non-system accounts.', 90, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(10, 1, 'finance', 'chart_of_accounts', 'allow_account_deactivation', '1', '1', 'BOOLEAN', NULL, 'Allow administrators to deactivate accounts instead of deleting them.', 100, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(11, 1, 'finance', 'chart_of_accounts', 'show_account_codes', '1', '1', 'BOOLEAN', NULL, 'Display account codes throughout the Finance module.', 110, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:24:07'),
(12, 1, 'finance', 'chart_of_accounts', 'show_inactive_accounts', '1', '0', 'BOOLEAN', NULL, 'Show inactive accounts by default in the Chart of Accounts.', 120, 0, 1, '2026-08-08 11:24:07', '2026-08-08 12:17:32'),
(13, 1, 'finance', 'chart_of_accounts', 'expand_tree_by_default', '1', '0', 'BOOLEAN', NULL, 'Expand the Chart of Accounts tree by default when the page opens.', 130, 0, 1, '2026-08-08 11:24:07', '2026-08-08 11:46:02'),
(14, 1, 'finance', 'chart_of_accounts', 'child_account_range', '100', '100', 'INTEGER', '{\"min\":10,\"max\":100000}', 'Numeric range reserved for child accounts under a parent account.', 35, 0, 1, '2026-08-08 13:46:46', '2026-08-08 14:51:24'),
