INSERT INTO `textbook_chapters` (`id`, `uuid`, `textbook_id`, `chapter_number`, `chapter_code`, `title`, `description`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'ead19e0a-ac1e-11f1-a393-ecd771b12399', 2, 4, 'chapter 4', 'Linear equations in two variables', NULL, 'Draft', 1, 1, '2026-09-09 07:20:21', '2026-09-09 07:20:21', NULL);
INSERT INTO `textbook_chapter_ingestions` (`id`, `uuid`, `chapter_revision_id`, `job_id`, `status`, `original_extraction`, `reviewed_extraction`, `error_message`, `quality_review_json`, `reviewed_by`, `approved_by`, `approved_at`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, '20539e4c-ac25-11f1-a393-ecd771b12399', 1, 1, 'Rejected', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter\": \"Chapter 4 — Linear equations in two variables\",\n        \"board_version\": \"BOSEM 2026-2027\"\n    },\n    \"pages\": [\n        {\n            \"pdf_page_number\": 1,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"CHAPTER 4\\nLINEAR EQUATIONS IN TWO VARIABLES\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.1 Introduction\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - √5 = 0, 5x + 3 = 3x - 5, x/2 - 3 = x/3 + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving equations in one variable (i.e. finding the value of the variable satisfying the equation).\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : Solve 4x + 3 = 15\\nSolution : 4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n∴ x = 12 / 4 = 3.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution : 4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n∴ x = 1.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Solve x/3 + 1 = x/4 - 2\\nSolution : x/3 + 1 = x/4 - 2\\nor x/3 - x/4 = -2 - 1 (by transposition)\\nor x/12 = -3\\n∴ y = -3 × 12 = -36.\"\n                }\n            ],\n            \"page_number\": \"70\"\n        },\n        {\n            \"pdf_page_number\": 2,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.2 Linear Equations in Two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \'x + y = 10\'. This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, x/3 + y/4 = 1 etc. are all linear equations in two variables.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.3 Solution of a Linear Equation in Two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables ? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 × 3 + 1 = 10.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation\"\n                }\n            ],\n            \"page_number\": \"71\"\n        },\n        {\n            \"pdf_page_number\": 3,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e. y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -5/2 for any value of y. Hence any three solutions of the given equation are (-5/2, 0), (-5/2, 1) and (-5/2, 2).\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"EXERCISE 4.1\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"1. Solve the following linear equations in one variable :\\n(i) x/3 = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) x/2 + 5 = x/3 + 7\\n(ix) (x + 2)/3 - (x - 1)/2 = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\"\n                }\n            ],\n            \"page_number\": \"73\"\n        },\n        {\n            \"pdf_page_number\": 4,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution : Let the cost of a notebook be x and that of a pen be y.\\nThen we have, x = 2y\\nor x - 2y = 0.\\nThis is the linear equation which represents the given statement.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\"\n                }\n            ],\n            \"page_number\": \"72\"\n        },\n        {\n            \"pdf_page_number\": 5,\n            \"blocks\": [\n                {\n                    \"type\": \"question\",\n                    \"content\": \"3. Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"ANSWERS\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"1. (i) -6 (ii) 3 (iii) 1 (iv) 4 (v) 13 (vi) 4 (vii) 3/2 (viii) 12 (ix) 1 (x) 7\\n2. (i) x - 8y = 0 (ii) x - y = 5 (iii) 2x + 3y = 12000 (iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, 1/3)\\n(ii) (0, 4), (3, 0), (-3, 8), (1, 8/3)\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -5/2)\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, 5/2), (1, 5/2), (2, 5/2), (3, 5/2)\\n4. (i) Yes (ii) No (iii) No (iv) Yes (v) Yes (vi) Yes\\n5. (i) 7 (ii) -7\"\n                }\n            ],\n            \"page_number\": \"74\"\n        },\n        {\n            \"pdf_page_number\": 6,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.4 Graph of a Linear Equation in two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line AB (Fig. 4.1). Also we see that the other two points lie on the line AB.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line AB may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line AB do not satisfy the equation. For example, the point Q(2, 1) is not on the line AB and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Thus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line AB;\\n(ii) the co-ordinates of every point on the line AB constitute a solution of equation (i);\\nand (iii) the co-ordinates of any point which does not lie on the line AB do not constitute a solution of equation (i).\"\n                }\n            ],\n            \"page_number\": \"75\"\n        },\n        {\n            \"pdf_page_number\": 7,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"So, the linear equation (i) is geometrically represented by the line AB. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : Draw the graph of x = 5.\\nSolution : x = 5 is a linear equation in one variable. However, it can be written as\\nx + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line AB (Fig. 4.2). The line AB thus obtained is the graph of the equation x = 5.\"\n                }\n            ],\n            \"page_number\": \"76\"\n        },\n        {\n            \"pdf_page_number\": 8,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Remarks : (i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Draw the graph of y = 4.\\nSolution : y = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The points represented by the above ordered pairs are plotted. Joining these points we get a straight line AB as shown in Fig. 4.3. The straight line AB is the graph of the equation y = 4.\"\n                }\n            ],\n            \"page_number\": \"77\"\n        },\n        {\n            \"pdf_page_number\": 9,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Remarks : (i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line AB as shown in Fig. 4.4. The straight line AB is the graph of the equation 3x + 5y = 15.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\"\n                }\n            ],\n            \"page_number\": \"78\"\n        },\n        {\n            \"pdf_page_number\": 10,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Solution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\"\n                }\n            ],\n            \"page_number\": \"79\"\n        }\n    ],\n    \"concepts\": [\n        {\n            \"title\": \"Linear equation in one variable\",\n            \"canonical_text\": \"An equation involving only linear polynomials in one variable. Equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants).\",\n            \"page_number\": \"70\",\n            \"summary\": \"Equations in one variable with degree 1 having a unique solution.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Linear Equation in Two Variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables. The general form is ax + by + c = 0.\",\n            \"page_number\": \"71\",\n            \"summary\": \"Equation of degree 1 involving two variables.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Solution of a Linear Equation in Two Variables\",\n            \"canonical_text\": \"A pair of values, one for x and one for y which satisfy the equation is called a solution of the equation, written as an ordered pair (x, y).\",\n            \"page_number\": \"71\",\n            \"summary\": \"Ordered pair satisfying the two-variable linear equation.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Graph of a Linear Equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions of the equation.\",\n            \"page_number\": \"75, 76\",\n            \"summary\": \"Geometric representation of solutions on a cartesian plane.\",\n            \"type\": \"concept\"\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in one variable\",\n            \"definition\": \"An equation involving only linear polynomials in one variable of the form ax = b, ax + b = c, ax + b = cx + d.\",\n            \"page_number\": \"70\"\n        },\n        {\n            \"term\": \"Linear equation in two variables\",\n            \"definition\": \"An equation of the form ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": \"71\"\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"latex\": \"ax + by + c = 0\",\n            \"page_number\": \"71\"\n        }\n    ],\n    \"examples\": [\n        {\n            \"number\": \"1\",\n            \"title\": \"Solve 4x + 3 = 15 (Linear equation in one variable example 1-3 series from page 70, 72, etc.)\"\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"4.1\",\n            \"title\": \"Graph of 2x + 3y = 12\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"graph/line plot\"\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question\": \"Solve the following linear equations in one variable : (i) x/3 = -2 ... (upto (x))\",\n            \"number\": \"1\",\n            \"page_number\": \"73\"\n        },\n        {\n            \"question\": \"Write linear equations in two variables to represent the following statements : (i) The cost of a pen is eight times that of a pencil. (ii) The difference of two numbers is 5.\",\n            \"number\": \"2\",\n            \"page_number\": \"73\"\n        },\n        {\n            \"question\": \"Find four different solutions for each of the following equations in two variables: (i) x = 3y ... (upto (vi))\",\n            \"number\": \"3\",\n            \"page_number\": \"74\"\n        },\n        {\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (i) (2, 0) ... (upto (vi))\",\n            \"number\": \"4\",\n            \"page_number\": \"74\"\n        },\n        {\n            \"question\": \"Find the value of k if (i) (1, 2) is a solution of 3x + 2y = k (ii) (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"number\": \"5\",\n            \"page_number\": \"74\"\n        }\n    ],\n    \"quality_flags\": []\n}', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter\": \"Chapter 4 — Linear equations in two variables\",\n        \"board_version\": \"BOSEM 2026-2027\"\n    },\n    \"pages\": [\n        {\n            \"pdf_page_number\": 1,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"CHAPTER 4\\nLINEAR EQUATIONS IN TWO VARIABLES\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.1 Introduction\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - √5 = 0, 5x + 3 = 3x - 5, x/2 - 3 = x/3 + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving equations in one variable (i.e. finding the value of the variable satisfying the equation).\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : Solve 4x + 3 = 15\\nSolution : 4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n∴ x = 12 / 4 = 3.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution : 4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n∴ x = 1.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Solve x/3 + 1 = x/4 - 2\\nSolution : x/3 + 1 = x/4 - 2\\nor x/3 - x/4 = -2 - 1 (by transposition)\\nor x/12 = -3\\n∴ y = -3 × 12 = -36.\"\n                }\n            ],\n            \"page_number\": \"70\"\n        },\n        {\n            \"pdf_page_number\": 2,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.2 Linear Equations in Two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \'x + y = 10\'. This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, x/3 + y/4 = 1 etc. are all linear equations in two variables.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.3 Solution of a Linear Equation in Two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables ? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 × 3 + 1 = 10.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation\"\n                }\n            ],\n            \"page_number\": \"71\"\n        },\n        {\n            \"pdf_page_number\": 3,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e. y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -5/2 for any value of y. Hence any three solutions of the given equation are (-5/2, 0), (-5/2, 1) and (-5/2, 2).\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"EXERCISE 4.1\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"1. Solve the following linear equations in one variable :\\n(i) x/3 = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) x/2 + 5 = x/3 + 7\\n(ix) (x + 2)/3 - (x - 1)/2 = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\"\n                }\n            ],\n            \"page_number\": \"73\"\n        },\n        {\n            \"pdf_page_number\": 4,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution : Let the cost of a notebook be x and that of a pen be y.\\nThen we have, x = 2y\\nor x - 2y = 0.\\nThis is the linear equation which represents the given statement.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\"\n                }\n            ],\n            \"page_number\": \"72\"\n        },\n        {\n            \"pdf_page_number\": 5,\n            \"blocks\": [\n                {\n                    \"type\": \"question\",\n                    \"content\": \"3. Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\"\n                },\n                {\n                    \"type\": \"question\",\n                    \"content\": \"5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\"\n                },\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"ANSWERS\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"1. (i) -6 (ii) 3 (iii) 1 (iv) 4 (v) 13 (vi) 4 (vii) 3/2 (viii) 12 (ix) 1 (x) 7\\n2. (i) x - 8y = 0 (ii) x - y = 5 (iii) 2x + 3y = 12000 (iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, 1/3)\\n(ii) (0, 4), (3, 0), (-3, 8), (1, 8/3)\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -5/2)\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, 5/2), (1, 5/2), (2, 5/2), (3, 5/2)\\n4. (i) Yes (ii) No (iii) No (iv) Yes (v) Yes (vi) Yes\\n5. (i) 7 (ii) -7\"\n                }\n            ],\n            \"page_number\": \"74\"\n        },\n        {\n            \"pdf_page_number\": 6,\n            \"blocks\": [\n                {\n                    \"type\": \"heading\",\n                    \"content\": \"4.4 Graph of a Linear Equation in two Variables\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line AB (Fig. 4.1). Also we see that the other two points lie on the line AB.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line AB may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line AB do not satisfy the equation. For example, the point Q(2, 1) is not on the line AB and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Thus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line AB;\\n(ii) the co-ordinates of every point on the line AB constitute a solution of equation (i);\\nand (iii) the co-ordinates of any point which does not lie on the line AB do not constitute a solution of equation (i).\"\n                }\n            ],\n            \"page_number\": \"75\"\n        },\n        {\n            \"pdf_page_number\": 7,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"So, the linear equation (i) is geometrically represented by the line AB. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 1 : Draw the graph of x = 5.\\nSolution : x = 5 is a linear equation in one variable. However, it can be written as\\nx + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line AB (Fig. 4.2). The line AB thus obtained is the graph of the equation x = 5.\"\n                }\n            ],\n            \"page_number\": \"76\"\n        },\n        {\n            \"pdf_page_number\": 8,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Remarks : (i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 2 : Draw the graph of y = 4.\\nSolution : y = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"The points represented by the above ordered pairs are plotted. Joining these points we get a straight line AB as shown in Fig. 4.3. The straight line AB is the graph of the equation y = 4.\"\n                }\n            ],\n            \"page_number\": \"77\"\n        },\n        {\n            \"pdf_page_number\": 9,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Remarks : (i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line AB as shown in Fig. 4.4. The straight line AB is the graph of the equation 3x + 5y = 15.\"\n                },\n                {\n                    \"type\": \"example\",\n                    \"content\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\"\n                }\n            ],\n            \"page_number\": \"78\"\n        },\n        {\n            \"pdf_page_number\": 10,\n            \"blocks\": [\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"Solution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\"\n                },\n                {\n                    \"type\": \"paragraph\",\n                    \"content\": \"To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\"\n                }\n            ],\n            \"page_number\": \"79\"\n        }\n    ],\n    \"concepts\": [\n        {\n            \"title\": \"Linear equation in one variable\",\n            \"canonical_text\": \"An equation involving only linear polynomials in one variable. Equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants).\",\n            \"page_number\": \"70\",\n            \"summary\": \"Equations in one variable with degree 1 having a unique solution.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Linear Equation in Two Variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables. The general form is ax + by + c = 0.\",\n            \"page_number\": \"71\",\n            \"summary\": \"Equation of degree 1 involving two variables.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Solution of a Linear Equation in Two Variables\",\n            \"canonical_text\": \"A pair of values, one for x and one for y which satisfy the equation is called a solution of the equation, written as an ordered pair (x, y).\",\n            \"page_number\": \"71\",\n            \"summary\": \"Ordered pair satisfying the two-variable linear equation.\",\n            \"type\": \"definition\"\n        },\n        {\n            \"title\": \"Graph of a Linear Equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions of the equation.\",\n            \"page_number\": \"75, 76\",\n            \"summary\": \"Geometric representation of solutions on a cartesian plane.\",\n            \"type\": \"concept\"\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in one variable\",\n            \"definition\": \"An equation involving only linear polynomials in one variable of the form ax = b, ax + b = c, ax + b = cx + d.\",\n            \"page_number\": \"70\"\n        },\n        {\n            \"term\": \"Linear equation in two variables\",\n            \"definition\": \"An equation of the form ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": \"71\"\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"latex\": \"ax + by + c = 0\",\n            \"page_number\": \"71\"\n        }\n    ],\n    \"examples\": [\n        {\n            \"number\": \"1\",\n            \"title\": \"Solve 4x + 3 = 15 (Linear equation in one variable example 1-3 series from page 70, 72, etc.)\"\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"4.1\",\n            \"title\": \"Graph of 2x + 3y = 12\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"graph/line plot\"\n        },\n        {\n            \"figure_number\": \"4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"graph/line plot\"\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question\": \"Solve the following linear equations in one variable : (i) x/3 = -2 ... (upto (x))\",\n            \"number\": \"1\",\n            \"page_number\": \"73\"\n        },\n        {\n            \"question\": \"Write linear equations in two variables to represent the following statements : (i) The cost of a pen is eight times that of a pencil. (ii) The difference of two numbers is 5.\",\n            \"number\": \"2\",\n            \"page_number\": \"73\"\n        },\n        {\n            \"question\": \"Find four different solutions for each of the following equations in two variables: (i) x = 3y ... (upto (vi))\",\n            \"number\": \"3\",\n            \"page_number\": \"74\"\n        },\n        {\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (i) (2, 0) ... (upto (vi))\",\n            \"number\": \"4\",\n            \"page_number\": \"74\"\n        },\n        {\n            \"question\": \"Find the value of k if (i) (1, 2) is a solution of 3x + 2y = k (ii) (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"number\": \"5\",\n            \"page_number\": \"74\"\n        }\n    ],\n    \"quality_flags\": []\n}', NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-09 08:04:48', '2026-09-11 14:32:00');
INSERT INTO `textbook_chapter_ingestions` (`id`, `uuid`, `chapter_revision_id`, `job_id`, `status`, `original_extraction`, `reviewed_extraction`, `error_message`, `quality_review_json`, `reviewed_by`, `approved_by`, `approved_at`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(2, 'ea08a6b4-adf2-11f1-8076-56d93faeab4e', 2, 2, 'NeedsReview', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"board_version\": \"BOSEM 2026-2027\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter_number\": \"4\",\n        \"chapter_title\": \"Linear equations in two variables\"\n    },\n    \"pages\": [\n        {\n            \"page_number\": 1,\n            \"text\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES 4.1 Introduction You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{3} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation). Example 1 : Solve 4x + 3 = 15 Solution : 4x + 3 = 15 or 4x = 15 - 3 (by transposition) or 4x = 12 \\\\therefore x = \\\\frac{12}{4} = 3. Example 2 : Solve 4x + 3 = 2x + 5 Solution : 4x + 3 = 2x + 5 or 4x - 2x = 5 - 3 (by transposition) or 2x = 2 \\\\therefore x = 1. Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2 Solution : \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2 or \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition) or \\\\frac{x}{12} = -3 \\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 2,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 71 4.2 Linear Equations in Two Variables Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables. Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables. The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes. If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0. 4.3 Solution of a Linear Equation in Two Variables You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10. This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 \\\\neq 10. You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 3,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 73 Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) also a solution of the given equation. Again, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation. Hence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2). (ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e. y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0. Again, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation. Similarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation. Hence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3). (iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2). EXERCISE 4.1 1. Solve the following linear equations in one variable : (i) \\\\frac{x}{3} = -2 (ii) 4x + 3 = 15 (iii) 3x + 2 = x + 4 (iv) 9x - 4 = 32 (v) 3y + 5(2 - y) = -16 (vi) 13t - 4(t + 8) - 4 = 0 (vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2) (viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7 (ix) \\\\frac{x + 2}{3} - \\\\frac{x - 1}{2} = 1 (x) 2(x - 15) = 5(x - 11) + 4 2. Write linear equations in two variables to represent the following statements : (i) The cost of a pen is eight times that of a pencil. (ii) The difference of two numbers is 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 4,\n            \"text\": \"72 MATHEMATICS FOR CLASS IX in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation. Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement. Solution : Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement. Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y. Solution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5. (ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5. (iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0. Example 3 : Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5 Solution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0. (ii) x = 2 can be written as x + 0.y - 2 = 0. (iii) 2y = 5 can be written as 0.x + 2y - 5 = 0. Example 4 : Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0. Solution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 5,\n            \"text\": \"74 MATHEMATICS FOR CLASS IX (iii) Two tables and three chairs cost \\\\rupee 1200. (iv) Two numbers are in the ratio 2 : 3. 3. Find four different solutions for each of the following equations in two variables: (i) x = 3y (ii) 4x + 3y = 12 (iii) x + 2y = 6 (iv) 5x + 2y = 0 (v) 3x + 4 = 0 (vi) 2y - 5 = 0 4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (i) (2, 0) (ii) (0, 3) (iii) (3, 0) (iv) (0, -3) (v) (-2, -6) (vi) (4, 3) 5. Find the value of k if (i) (1, 2) is a solution of 3x + 2y = k (ii) (2, -3) is a solution of kx - 3y + 5 = 0. ANSWERS 1. (i) -6 (ii) 3 (iii) 1 (iv) 4 (v) 13 (vi) 4 (vii) \\\\frac{3}{2} (viii) 12 (ix) 1 (x) 7 2. (i) x - 8y = 0 (ii) x - y = 5 (iii) 2x + 3y = 12000 (iv) 3x - 2y = 0 3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3}) (ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3}) (iii) (0, 3), (6, 0), (2, 2), (-2, 4) (iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2}) (v) (-4, 0), (-4, 1), (-4, 2), (-4, 3) (vi) (0, \\\\frac{5}{2}), (1, \\\\frac{7}{2}), (2, \\\\frac{9}{2}), (3, \\\\frac{11}{2}) 4. (i) Yes (ii) No (iii) No (iv) Yes (v) Yes (vi) Yes 5. (i) 7 (ii) -7\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 6,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 75 4.4 Graph of a Linear Equation in two Variables From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation : 2x + 3y = 12 ... (i) Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}. Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation. Thus, we observe that (i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB}; (ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i); and (iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 7,\n            \"text\": \"76 MATHEMATICS FOR CLASS IX So, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph. Example 1 : Draw the graph of x = 5. Solution : x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 8,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 77 Remarks : (i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c. (ii) The graph of x = 0 is the Y-axis. Example 2 : Draw the graph of y = 4. Solution : y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 9,\n            \"text\": \"78 MATHEMATICS FOR CLASS IX Remarks : (i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c. (ii) The graph of y = 0 is the X-axis. Example 3 : Draw the graph of 3x + 5y = 15. Solution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15. Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 10,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 79 Solution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"quality_flags\": []\n        }\n    ],\n    \"concepts\": [\n        {\n            \"name\": \"Linear equation in one variable\",\n            \"canonical_text\": \"A linear equation in one variable is an equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Linear equation in two variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Solution of a linear equation in two variables\",\n            \"canonical_text\": \"A pair of values, one for x and one for y which satisfy the equation is called a solution of the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Graph of a linear equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in two variables (General Form)\",\n            \"definition\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"canonical_text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"examples\": [\n        {\n            \"title\": \"Example 1 (Page 1)\",\n            \"question\": \"Solve 4x + 3 = 15\",\n            \"solution\": \"4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n\\\\therefore x = \\\\frac{12}{4} = 3.\",\n            \"canonical_text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution : 4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n\\\\therefore x = \\\\frac{12}{4} = 3.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 1)\",\n            \"question\": \"Solve 4x + 3 = 2x + 5\",\n            \"solution\": \"4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n\\\\therefore x = 1.\",\n            \"canonical_text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution : 4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n\\\\therefore x = 1.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 1)\",\n            \"question\": \"Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\",\n            \"solution\": \"\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition)\\nor \\\\frac{x}{12} = -3\\n\\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"canonical_text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nSolution : \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition)\\nor \\\\frac{x}{12} = -3\\n\\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1 (Page 4)\",\n            \"question\": \"The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\",\n            \"solution\": \"Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement.\",\n            \"canonical_text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution : Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 4)\",\n            \"question\": \"Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\",\n            \"solution\": \"(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"canonical_text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5. (ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5. (iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 4)\",\n            \"question\": \"Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5\",\n            \"solution\": \"(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"canonical_text\": \"Example 3 : Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5\\nSolution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0. (ii) x = 2 can be written as x + 0.y - 2 = 0. (iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4 (Page 4)\",\n            \"question\": \"Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0.\",\n            \"solution\": \"(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"canonical_text\": \"Example 4 : Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0.\\nSolution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1 (Page 7)\",\n            \"question\": \"Draw the graph of x = 5.\",\n            \"solution\": \"x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"canonical_text\": \"Example 1 : Draw the graph of x = 5.\\nSolution : x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 8)\",\n            \"question\": \"Draw the graph of y = 4.\",\n            \"solution\": \"y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"canonical_text\": \"Example 2 : Draw the graph of y = 4.\\nSolution : y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 9)\",\n            \"question\": \"Draw the graph of 3x + 5y = 15.\",\n            \"solution\": \"3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"canonical_text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4 (Page 9)\",\n            \"question\": \"If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"solution\": \"Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below.\",\n            \"canonical_text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\\nSolution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"4.1\",\n            \"title\": \"Graph of 2x + 3y = 12\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the straight line graph of the linear equation 2x + 3y = 12 passing through points A(-3, 6), (0, 4), (3, 2), (6, 0), P(9, -2) and Q(2, 1).\",\n            \"equations\": [\n                \"2x + 3y = 12\"\n            ],\n            \"labelled_points\": [\n                \"A(-3, 6)\",\n                \"(0, 4)\",\n                \"(3, 2)\",\n                \"Q(2, 1)\",\n                \"(6, 0)\",\n                \"P(9, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 6,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the vertical line x = 5 parallel to the Y-axis.\",\n            \"equations\": [\n                \"x = 5\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 5)\",\n                \"(5, 2)\",\n                \"(5, 0)\",\n                \"(5, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 7,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the horizontal line y = 4 parallel to the X-axis.\",\n            \"equations\": [\n                \"y = 4\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-3, 4)\",\n                \"(0, 4)\",\n                \"(2, 4)\",\n                \"(5, 4)\",\n                \"B\"\n            ],\n            \"page_number\": 8,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the straight line graph of 3x + 5y = 15.\",\n            \"equations\": [\n                \"3x + 5y = 15\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-5, 6)\",\n                \"(0, 3)\",\n                \"(5, 0)\",\n                \"(10, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 9,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the linear graph for work and distance y = 2x.\",\n            \"equations\": [\n                \"y = 2x\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 10)\",\n                \"(4, 8)\",\n                \"(2, 4)\",\n                \"(0, 0)\",\n                \"(-1, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 10,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question_number\": \"1.(i)\",\n            \"question\": \"\\\\frac{x}{3} = -2\",\n            \"answer\": \"-6\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ii)\",\n            \"question\": \"4x + 3 = 15\",\n            \"answer\": \"3\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iii)\",\n            \"question\": \"3x + 2 = x + 4\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iv)\",\n            \"question\": \"9x - 4 = 32\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(v)\",\n            \"question\": \"3y + 5(2 - y) = -16\",\n            \"answer\": \"13\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vi)\",\n            \"question\": \"13t - 4(t + 8) - 4 = 0\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vii)\",\n            \"question\": \"(x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\",\n            \"answer\": \"\\\\frac{3}{2}\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(viii)\",\n            \"question\": \"\\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\",\n            \"answer\": \"12\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ix)\",\n            \"question\": \"\\\\frac{x + 2}{3} - \\\\frac{x - 1}{2} = 1\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(x)\",\n            \"question\": \"2(x - 15) = 5(x - 11) + 4\",\n            \"answer\": \"7\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(i)\",\n            \"question\": \"The cost of a pen is eight times that of a pencil.\",\n            \"answer\": \"x - 8y = 0\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(ii)\",\n            \"question\": \"The difference of two numbers is 5.\",\n            \"answer\": \"x - y = 5\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iii)\",\n            \"question\": \"Two tables and three chairs cost \\\\rupee 1200.\",\n            \"answer\": \"2x + 3y = 12000\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iv)\",\n            \"question\": \"Two numbers are in the ratio 2 : 3.\",\n            \"answer\": \"3x - 2y = 0\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(i)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: x = 3y\",\n            \"answer\": \"(0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(ii)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 4x + 3y = 12\",\n            \"answer\": \"(0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iii)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: x + 2y = 6\",\n            \"answer\": \"(0, 3), (6, 0), (2, 2), (-2, 4)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iv)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 5x + 2y = 0\",\n            \"answer\": \"(0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(v)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 3x + 4 = 0\",\n            \"answer\": \"(-4, 0), (-4, 1), (-4, 2), (-4, 3)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(vi)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 2y - 5 = 0\",\n            \"answer\": \"(0, \\\\frac{5}{2}), (1, \\\\frac{7}{2}), (2, \\\\frac{9}{2}), (3, \\\\frac{11}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(i)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (2, 0)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(ii)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (0, 3)\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iii)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (3, 0)\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iv)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (0, -3)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(v)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (-2, -6)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(vi)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (4, 3)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(i)\",\n            \"question\": \"Find the value of k if (1, 2) is a solution of 3x + 2y = k\",\n            \"answer\": \"7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(ii)\",\n            \"question\": \"Find the value of k if (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"answer\": \"-7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        }\n    ],\n    \"quality_flags\": []\n}', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"board_version\": \"BOSEM 2026-2027\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter_number\": \"4\",\n        \"chapter_title\": \"Linear equations in two variables\"\n    },\n    \"pages\": [\n        {\n            \"page_number\": 1,\n            \"text\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES 4.1 Introduction You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{3} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation). Example 1 : Solve 4x + 3 = 15 Solution : 4x + 3 = 15 or 4x = 15 - 3 (by transposition) or 4x = 12 \\\\therefore x = \\\\frac{12}{4} = 3. Example 2 : Solve 4x + 3 = 2x + 5 Solution : 4x + 3 = 2x + 5 or 4x - 2x = 5 - 3 (by transposition) or 2x = 2 \\\\therefore x = 1. Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2 Solution : \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2 or \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition) or \\\\frac{x}{12} = -3 \\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 2,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 71 4.2 Linear Equations in Two Variables Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables. Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables. The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes. If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0. 4.3 Solution of a Linear Equation in Two Variables You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10. This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 \\\\neq 10. You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 3,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 73 Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) also a solution of the given equation. Again, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation. Hence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2). (ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e. y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0. Again, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation. Similarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation. Hence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3). (iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2). EXERCISE 4.1 1. Solve the following linear equations in one variable : (i) \\\\frac{x}{3} = -2 (ii) 4x + 3 = 15 (iii) 3x + 2 = x + 4 (iv) 9x - 4 = 32 (v) 3y + 5(2 - y) = -16 (vi) 13t - 4(t + 8) - 4 = 0 (vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2) (viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7 (ix) \\\\frac{x + 2}{3} - \\\\frac{x - 1}{2} = 1 (x) 2(x - 15) = 5(x - 11) + 4 2. Write linear equations in two variables to represent the following statements : (i) The cost of a pen is eight times that of a pencil. (ii) The difference of two numbers is 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 4,\n            \"text\": \"72 MATHEMATICS FOR CLASS IX in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation. Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement. Solution : Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement. Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y. Solution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5. (ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5. (iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0. Example 3 : Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5 Solution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0. (ii) x = 2 can be written as x + 0.y - 2 = 0. (iii) 2y = 5 can be written as 0.x + 2y - 5 = 0. Example 4 : Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0. Solution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 5,\n            \"text\": \"74 MATHEMATICS FOR CLASS IX (iii) Two tables and three chairs cost \\\\rupee 1200. (iv) Two numbers are in the ratio 2 : 3. 3. Find four different solutions for each of the following equations in two variables: (i) x = 3y (ii) 4x + 3y = 12 (iii) x + 2y = 6 (iv) 5x + 2y = 0 (v) 3x + 4 = 0 (vi) 2y - 5 = 0 4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (i) (2, 0) (ii) (0, 3) (iii) (3, 0) (iv) (0, -3) (v) (-2, -6) (vi) (4, 3) 5. Find the value of k if (i) (1, 2) is a solution of 3x + 2y = k (ii) (2, -3) is a solution of kx - 3y + 5 = 0. ANSWERS 1. (i) -6 (ii) 3 (iii) 1 (iv) 4 (v) 13 (vi) 4 (vii) \\\\frac{3}{2} (viii) 12 (ix) 1 (x) 7 2. (i) x - 8y = 0 (ii) x - y = 5 (iii) 2x + 3y = 12000 (iv) 3x - 2y = 0 3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3}) (ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3}) (iii) (0, 3), (6, 0), (2, 2), (-2, 4) (iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2}) (v) (-4, 0), (-4, 1), (-4, 2), (-4, 3) (vi) (0, \\\\frac{5}{2}), (1, \\\\frac{7}{2}), (2, \\\\frac{9}{2}), (3, \\\\frac{11}{2}) 4. (i) Yes (ii) No (iii) No (iv) Yes (v) Yes (vi) Yes 5. (i) 7 (ii) -7\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 6,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 75 4.4 Graph of a Linear Equation in two Variables From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation : 2x + 3y = 12 ... (i) Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}. Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation. Thus, we observe that (i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB}; (ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i); and (iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 7,\n            \"text\": \"76 MATHEMATICS FOR CLASS IX So, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph. Example 1 : Draw the graph of x = 5. Solution : x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 8,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 77 Remarks : (i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c. (ii) The graph of x = 0 is the Y-axis. Example 2 : Draw the graph of y = 4. Solution : y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 9,\n            \"text\": \"78 MATHEMATICS FOR CLASS IX Remarks : (i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c. (ii) The graph of y = 0 is the X-axis. Example 3 : Draw the graph of 3x + 5y = 15. Solution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15. Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 10,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 79 Solution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"quality_flags\": []\n        }\n    ],\n    \"concepts\": [\n        {\n            \"name\": \"Linear equation in one variable\",\n            \"canonical_text\": \"A linear equation in one variable is an equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Linear equation in two variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Solution of a linear equation in two variables\",\n            \"canonical_text\": \"A pair of values, one for x and one for y which satisfy the equation is called a solution of the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Graph of a linear equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in two variables (General Form)\",\n            \"definition\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"canonical_text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"examples\": [\n        {\n            \"title\": \"Example 1 (Page 1)\",\n            \"question\": \"Solve 4x + 3 = 15\",\n            \"solution\": \"4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n\\\\therefore x = \\\\frac{12}{4} = 3.\",\n            \"canonical_text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution : 4x + 3 = 15\\nor 4x = 15 - 3 (by transposition)\\nor 4x = 12\\n\\\\therefore x = \\\\frac{12}{4} = 3.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 1)\",\n            \"question\": \"Solve 4x + 3 = 2x + 5\",\n            \"solution\": \"4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n\\\\therefore x = 1.\",\n            \"canonical_text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution : 4x + 3 = 2x + 5\\nor 4x - 2x = 5 - 3 (by transposition)\\nor 2x = 2\\n\\\\therefore x = 1.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 1)\",\n            \"question\": \"Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\",\n            \"solution\": \"\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition)\\nor \\\\frac{x}{12} = -3\\n\\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"canonical_text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nSolution : \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor \\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1 (by transposition)\\nor \\\\frac{x}{12} = -3\\n\\\\therefore y = -3 \\\\times 12 = -36.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1 (Page 4)\",\n            \"question\": \"The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\",\n            \"solution\": \"Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement.\",\n            \"canonical_text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution : Let the cost of a notebook be x and that of a pen be y. Then we have, x = 2y or x - 2y = 0. This is the linear equation which represents the given statement.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 4)\",\n            \"question\": \"Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\",\n            \"solution\": \"(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"canonical_text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case : (i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution : (i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5. (ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5. (iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 4)\",\n            \"question\": \"Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5\",\n            \"solution\": \"(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"canonical_text\": \"Example 3 : Write each of the following as an equation in two variables : (i) 4x = 3 (ii) x = -2 (iii) 2y = 5\\nSolution : (i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0. (ii) x = 2 can be written as x + 0.y - 2 = 0. (iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4 (Page 4)\",\n            \"question\": \"Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0.\",\n            \"solution\": \"(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"canonical_text\": \"Example 4 : Find any three different solutions for each of the following equations : (i) 2x + 3y = 6 (ii) 3x + 4y = 0 (iii) 2x + 5 = 0.\\nSolution : (i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1 (Page 7)\",\n            \"question\": \"Draw the graph of x = 5.\",\n            \"solution\": \"x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"canonical_text\": \"Example 1 : Draw the graph of x = 5.\\nSolution : x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc. The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2 (Page 8)\",\n            \"question\": \"Draw the graph of y = 4.\",\n            \"solution\": \"y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"canonical_text\": \"Example 2 : Draw the graph of y = 4.\\nSolution : y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc. The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3 (Page 9)\",\n            \"question\": \"Draw the graph of 3x + 5y = 15.\",\n            \"solution\": \"3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"canonical_text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution : 3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4 (Page 9)\",\n            \"question\": \"If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"solution\": \"Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below.\",\n            \"canonical_text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\\nSolution : Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the force be y units. It is given that y \\\\propto x. If k be the constant force acting on the body (which is also the constant of proportionality), then y = kx, which is the linear equation representing the given statement. If k = 2 units, the above equation becomes y = 2x. To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"4.1\",\n            \"title\": \"Graph of 2x + 3y = 12\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the straight line graph of the linear equation 2x + 3y = 12 passing through points A(-3, 6), (0, 4), (3, 2), (6, 0), P(9, -2) and Q(2, 1).\",\n            \"equations\": [\n                \"2x + 3y = 12\"\n            ],\n            \"labelled_points\": [\n                \"A(-3, 6)\",\n                \"(0, 4)\",\n                \"(3, 2)\",\n                \"Q(2, 1)\",\n                \"(6, 0)\",\n                \"P(9, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 6,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the vertical line x = 5 parallel to the Y-axis.\",\n            \"equations\": [\n                \"x = 5\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 5)\",\n                \"(5, 2)\",\n                \"(5, 0)\",\n                \"(5, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 7,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the horizontal line y = 4 parallel to the X-axis.\",\n            \"equations\": [\n                \"y = 4\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-3, 4)\",\n                \"(0, 4)\",\n                \"(2, 4)\",\n                \"(5, 4)\",\n                \"B\"\n            ],\n            \"page_number\": 8,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the straight line graph of 3x + 5y = 15.\",\n            \"equations\": [\n                \"3x + 5y = 15\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-5, 6)\",\n                \"(0, 3)\",\n                \"(5, 0)\",\n                \"(10, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 9,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"Cartesian Graph\",\n            \"description\": \"Cartesian plane showing the linear graph for work and distance y = 2x.\",\n            \"equations\": [\n                \"y = 2x\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 10)\",\n                \"(4, 8)\",\n                \"(2, 4)\",\n                \"(0, 0)\",\n                \"(-1, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 10,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question_number\": \"1.(i)\",\n            \"question\": \"\\\\frac{x}{3} = -2\",\n            \"answer\": \"-6\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ii)\",\n            \"question\": \"4x + 3 = 15\",\n            \"answer\": \"3\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iii)\",\n            \"question\": \"3x + 2 = x + 4\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iv)\",\n            \"question\": \"9x - 4 = 32\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(v)\",\n            \"question\": \"3y + 5(2 - y) = -16\",\n            \"answer\": \"13\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vi)\",\n            \"question\": \"13t - 4(t + 8) - 4 = 0\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vii)\",\n            \"question\": \"(x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\",\n            \"answer\": \"\\\\frac{3}{2}\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(viii)\",\n            \"question\": \"\\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\",\n            \"answer\": \"12\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ix)\",\n            \"question\": \"\\\\frac{x + 2}{3} - \\\\frac{x - 1}{2} = 1\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(x)\",\n            \"question\": \"2(x - 15) = 5(x - 11) + 4\",\n            \"answer\": \"7\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(i)\",\n            \"question\": \"The cost of a pen is eight times that of a pencil.\",\n            \"answer\": \"x - 8y = 0\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(ii)\",\n            \"question\": \"The difference of two numbers is 5.\",\n            \"answer\": \"x - y = 5\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iii)\",\n            \"question\": \"Two tables and three chairs cost \\\\rupee 1200.\",\n            \"answer\": \"2x + 3y = 12000\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iv)\",\n            \"question\": \"Two numbers are in the ratio 2 : 3.\",\n            \"answer\": \"3x - 2y = 0\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(i)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: x = 3y\",\n            \"answer\": \"(0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(ii)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 4x + 3y = 12\",\n            \"answer\": \"(0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iii)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: x + 2y = 6\",\n            \"answer\": \"(0, 3), (6, 0), (2, 2), (-2, 4)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iv)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 5x + 2y = 0\",\n            \"answer\": \"(0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(v)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 3x + 4 = 0\",\n            \"answer\": \"(-4, 0), (-4, 1), (-4, 2), (-4, 3)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(vi)\",\n            \"question\": \"Find four different solutions for each of the following equations in two variables: 2y - 5 = 0\",\n            \"answer\": \"(0, \\\\frac{5}{2}), (1, \\\\frac{7}{2}), (2, \\\\frac{9}{2}), (3, \\\\frac{11}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(i)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (2, 0)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(ii)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (0, 3)\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iii)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (3, 0)\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iv)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (0, -3)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(v)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (-2, -6)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(vi)\",\n            \"question\": \"Check which of the following are solutions of the equation 3x - 2y = 6 and which are not : (4, 3)\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(i)\",\n            \"question\": \"Find the value of k if (1, 2) is a solution of 3x + 2y = k\",\n            \"answer\": \"7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(ii)\",\n            \"question\": \"Find the value of k if (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"answer\": \"-7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        }\n    ],\n    \"quality_flags\": []\n}', NULL, NULL, NULL, NULL, NULL, 1, 1, '2026-09-11 15:10:24', '2026-09-11 17:38:57');
INSERT INTO `textbook_chapter_ingestions` (`id`, `uuid`, `chapter_revision_id`, `job_id`, `status`, `original_extraction`, `reviewed_extraction`, `error_message`, `quality_review_json`, `reviewed_by`, `approved_by`, `approved_at`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(3, '4a6e2678-ae16-11f1-8076-56d93faeab4e', 3, 3, 'NeedsReview', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"board_version\": \"BOSEM 2026-2027\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter_number\": \"Chapter 4\",\n        \"chapter_title\": \"Linear equations in two variables\"\n    },\n    \"pages\": [\n        {\n            \"page_number\": 1,\n            \"text\": \"CHAPTER\\n4\\nLINEAR EQUATIONS IN TWO VARIABLES\\n\\n4.1 Introduction\\nYou have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{5} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation).\\n\\nExample 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\\n\\nExample 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\\n\\nExample 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"page_number\": 2,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 71\\n\\n4.2 Linear Equations in Two Variables\\nLet us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables.\\n\\nThus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\\n\\nThe general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\\n\\nIf either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\\n\\n4.3 Solution of a Linear Equation in Two Variables\\nYou have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10.\\n\\nThis solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\\n\\nYou have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 3,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 73\\n\\nSimilarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\\n\\n(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e., y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\\n\\n(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2).\\n\\nEXERCISE 4.1\\n1. Solve the following linear equations in one variable :\\n(i) \\\\frac{x}{3} = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\\n(ix) \\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\\n\\n2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\",\n            \"quality_flags\": [\n                \"Check formatting in Ex 4.1 question 1 (ix): expression contains two equals signs in source.\"\n            ]\n        },\n        {\n            \"page_number\": 4,\n            \"text\": \"MATHEMATICS FOR CLASS IX 72\\nin two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\\n\\nExample 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\\n\\nExample 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\\n\\nExample 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\\n\\nExample 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"page_number\": 5,\n            \"text\": \"74 MATHEMATICS FOR CLASS IX\\n(iii) Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\\n\\n3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\\n\\n4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\\n\\n5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\\n\\nANSWERS\\n1. (i) -6\\n(ii) 3\\n(iii) 1\\n(iv) 4\\n(v) 13\\n(vi) 4\\n(vii) \\\\frac{3}{2}\\n(viii) 12\\n(ix) 1\\n(x) 7\\n2. (i) x - 8y = 0\\n(ii) x - y = 5\\n(iii) 2x + 3y = 12000\\n(iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\\n(ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, \\\\frac{5}{2}), (1, \\\\frac{5}{2}), (2, \\\\frac{5}{2}), (3, \\\\frac{5}{2})\\n4. (i) Yes\\n(ii) No\\n(iii) No\\n(iv) Yes\\n(v) Yes\\n(vi) Yes\\n5. (i) 7\\n(ii) -7\",\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"page_number\": 6,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 75\\n\\n4.4 Graph of a Linear Equation in two Variables\\nFrom the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\\n\\nSome of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}.\\n\\nNow, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\\n\\nThus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB};\\n(ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i);\\nand\\n(iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 7,\n            \"text\": \"76 MATHEMATICS FOR CLASS IX\\nSo, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\\n\\nExample 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\\n\\nThe points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 8,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 77\\nRemarks :\\n(i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\\n\\nExample 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\\n\\nThe points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 9,\n            \"text\": \"78 MATHEMATICS FOR CLASS IX\\nRemarks :\\n(i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\\n\\nExample 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\\n\\nExample 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 10,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 79\\nSolution :\\nHere the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\\n\\nTo draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"quality_flags\": []\n        }\n    ],\n    \"page_blocks\": [\n        {\n            \"order\": 1,\n            \"block_type\": \"heading\",\n            \"text\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES\",\n            \"title\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES\",\n            \"level\": 1,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 2,\n            \"block_type\": \"heading\",\n            \"text\": \"4.1 Introduction\",\n            \"title\": \"4.1 Introduction\",\n            \"level\": 2,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 3,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{5} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 4,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 5,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 6,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"order\": 7,\n            \"block_type\": \"heading\",\n            \"text\": \"4.2 Linear Equations in Two Variables\",\n            \"title\": \"4.2 Linear Equations in Two Variables\",\n            \"level\": 2,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 8,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 9,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 10,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 11,\n            \"block_type\": \"paragraph\",\n            \"text\": \"If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 12,\n            \"block_type\": \"heading\",\n            \"text\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"title\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"level\": 2,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 13,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 14,\n            \"block_type\": \"paragraph\",\n            \"text\": \"This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 15,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 16,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 17,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e., y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 18,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 19,\n            \"block_type\": \"heading\",\n            \"text\": \"EXERCISE 4.1\",\n            \"title\": \"EXERCISE 4.1\",\n            \"level\": 1,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 20,\n            \"block_type\": \"question\",\n            \"text\": \"1. Solve the following linear equations in one variable :\\n(i) \\\\frac{x}{3} = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\\n(ix) \\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\",\n            \"title\": \"1\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": [\n                \"Check formatting in Ex 4.1 question 1 (ix): expression contains two equals signs in source.\"\n            ]\n        },\n        {\n            \"order\": 21,\n            \"block_type\": \"question\",\n            \"text\": \"2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\",\n            \"title\": \"2\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 22,\n            \"block_type\": \"paragraph\",\n            \"text\": \"in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 23,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 24,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 25,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"order\": 26,\n            \"block_type\": \"example\",\n            \"text\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"title\": \"Example 4\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 27,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(iii) Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 28,\n            \"block_type\": \"question\",\n            \"text\": \"3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\",\n            \"title\": \"3\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 29,\n            \"block_type\": \"question\",\n            \"text\": \"4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\",\n            \"title\": \"4\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 30,\n            \"block_type\": \"question\",\n            \"text\": \"5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"title\": \"5\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 31,\n            \"block_type\": \"answer\",\n            \"text\": \"ANSWERS\\n1. (i) -6\\n(ii) 3\\n(iii) 1\\n(iv) 4\\n(v) 13\\n(vi) 4\\n(vii) \\\\frac{3}{2}\\n(viii) 12\\n(ix) 1\\n(x) 7\\n2. (i) x - 8y = 0\\n(ii) x - y = 5\\n(iii) 2x + 3y = 12000\\n(iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\\n(ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, \\\\frac{5}{2}), (1, \\\\frac{5}{2}), (2, \\\\frac{5}{2}), (3, \\\\frac{5}{2})\\n4. (i) Yes\\n(ii) No\\n(iii) No\\n(iv) Yes\\n(v) Yes\\n(vi) Yes\\n5. (i) 7\\n(ii) -7\",\n            \"title\": \"ANSWERS\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"order\": 32,\n            \"block_type\": \"heading\",\n            \"text\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"title\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"level\": 2,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 33,\n            \"block_type\": \"paragraph\",\n            \"text\": \"From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 34,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 35,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 36,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Thus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB};\\n(ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i);\\nand\\n(iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 37,\n            \"block_type\": \"paragraph\",\n            \"text\": \"So, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 38,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as\\nx + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 39,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 40,\n            \"block_type\": \"note\",\n            \"text\": \"Remarks :\\n(i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\",\n            \"title\": \"Remarks\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 41,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 42,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 43,\n            \"block_type\": \"note\",\n            \"text\": \"Remarks :\\n(i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\",\n            \"title\": \"Remarks\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 44,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 45,\n            \"block_type\": \"example\",\n            \"text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"title\": \"Example 4\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 46,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 10,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 47,\n            \"block_type\": \"paragraph\",\n            \"text\": \"To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 10,\n            \"quality_flags\": []\n        }\n    ],\n    \"headings\": [\n        {\n            \"title\": \"4.1 Introduction\",\n            \"level\": 2,\n            \"canonical_text\": \"4.1 Introduction\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.2 Linear Equations in Two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.2 Linear Equations in Two Variables\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"EXERCISE 4.1\",\n            \"level\": 1,\n            \"canonical_text\": \"EXERCISE 4.1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"page_number\": 6,\n            \"quality_flags\": []\n        }\n    ],\n    \"concepts\": [\n        {\n            \"name\": \"Linear equation in one variable\",\n            \"canonical_text\": \"A linear equation in one variable is an equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Linear equation in two variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Solution of a linear equation in two variables\",\n            \"canonical_text\": \"If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Graph of a linear equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in one variable\",\n            \"definition\": \"An equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"term\": \"Linear equation in two variables\",\n            \"definition\": \"A linear polynomial in two variables equated to zero, also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"term\": \"Solution of a linear equation in two variables\",\n            \"definition\": \"A pair of values, one for x and one for y which satisfy the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"canonical_text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"examples\": [\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"Solve 4x + 3 = 15\",\n            \"solution\": \"4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"canonical_text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Solve 4x + 3 = 2x + 5\",\n            \"solution\": \"4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"canonical_text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\",\n            \"solution\": \"\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"canonical_text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"page_number\": 1,\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\",\n            \"solution\": \"Let the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"canonical_text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\",\n            \"solution\": \"(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"canonical_text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\",\n            \"solution\": \"(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"canonical_text\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"title\": \"Example 4\",\n            \"question\": \"Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\",\n            \"solution\": \"(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"canonical_text\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"Draw the graph of x = 5.\",\n            \"solution\": \"x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"canonical_text\": \"Example 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Draw the graph of y = 4.\",\n            \"solution\": \"y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"canonical_text\": \"Example 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Draw the graph of 3x + 5y = 15.\",\n            \"solution\": \"3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4.\",\n            \"canonical_text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4\",\n            \"question\": \"If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"solution\": \"Let x be the distance travelled and y be the work done. y = kx. For k = 2, y = 2x.\",\n            \"canonical_text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\\nSolution :\\nHere the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"Fig. 4.1\",\n            \"title\": \"Cartesian plane with straight line AB for 2x + 3y = 12\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing line AB passing through points A(-3, 6), (0, 4), Q(2, 1), (3, 2), (6, 0), P(9, -2), B.\",\n            \"equations\": [\n                \"2x + 3y = 12\"\n            ],\n            \"labelled_points\": [\n                \"A(-3, 6)\",\n                \"(0, 4)\",\n                \"Q(2, 1)\",\n                \"(3, 2)\",\n                \"\\\\mathbf{Q}(2, 1)\",\n                \"(6, 0)\",\n                \"P(9, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 6,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing vertical line AB representing x = 5.\",\n            \"equations\": [\n                \"x = 5\",\n                \"x + 0.y = 5\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 5)\",\n                \"(5, 2)\",\n                \"(5, 0)\",\n                \"(5, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 7,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing horizontal line AB representing y = 4.\",\n            \"equations\": [\n                \"y = 4\",\n                \"0.x + y = 4\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-3, 4)\",\n                \"(0, 4)\",\n                \"(2, 4)\",\n                \"(5, 4)\",\n                \"B\"\n            ],\n            \"page_number\": 8,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing straight line AB for 3x + 5y = 15.\",\n            \"equations\": [\n                \"3x + 5y = 15\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-5, 6)\",\n                \"(0, 3)\",\n                \"(5, 0)\",\n                \"(10, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 9,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing straight line AB for y = 2x.\",\n            \"equations\": [\n                \"y = 2x\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 10)\",\n                \"(4, 8)\",\n                \"(2, 4)\",\n                \"(0, 0)\",\n                \"(-1, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 10,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question_number\": \"1.(i)\",\n            \"question\": \"\\\\frac{x}{3} = -2\",\n            \"answer\": \"-6\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ii)\",\n            \"question\": \"4x + 3 = 15\",\n            \"answer\": \"3\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iii)\",\n            \"question\": \"3x + 2 = x + 4\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iv)\",\n            \"question\": \"9x - 4 = 32\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(v)\",\n            \"question\": \"3y + 5(2 - y) = -16\",\n            \"answer\": \"13\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vi)\",\n            \"question\": \"13t - 4(t + 8) - 4 = 0\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vii)\",\n            \"question\": \"(x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\",\n            \"answer\": \"\\\\frac{3}{2}\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(viii)\",\n            \"question\": \"\\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\",\n            \"answer\": \"12\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ix)\",\n            \"question\": \"\\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(x)\",\n            \"question\": \"2(x - 15) = 5(x - 11) + 4\",\n            \"answer\": \"7\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(i)\",\n            \"question\": \"The cost of a pen is eight times that of a pencil.\",\n            \"answer\": \"x - 8y = 0\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(ii)\",\n            \"question\": \"The difference of two numbers is 5.\",\n            \"answer\": \"x - y = 5\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iii)\",\n            \"question\": \"Two tables and three chairs cost ₹ 1200.\",\n            \"answer\": \"2x + 3y = 12000\",\n            \"page_number\": 5,\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"question_number\": \"2.(iv)\",\n            \"question\": \"Two numbers are in the ratio 2 : 3.\",\n            \"answer\": \"3x - 2y = 0\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(i)\",\n            \"question\": \"x = 3y\",\n            \"answer\": \"(0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(ii)\",\n            \"question\": \"4x + 3y = 12\",\n            \"answer\": \"(0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iii)\",\n            \"question\": \"x + 2y = 6\",\n            \"answer\": \"(0, 3), (6, 0), (2, 2), (-2, 4)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iv)\",\n            \"question\": \"5x + 2y = 0\",\n            \"answer\": \"(0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(v)\",\n            \"question\": \"3x + 4 = 0\",\n            \"answer\": \"(-4, 0), (-4, 1), (-4, 2), (-4, 3)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(vi)\",\n            \"question\": \"2y - 5 = 0\",\n            \"answer\": \"(0, \\\\frac{5}{2}), (1, \\\\frac{5}{2}), (2, \\\\frac{5}{2}), (3, \\\\frac{5}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(i)\",\n            \"question\": \"(2, 0) for 3x - 2y = 6\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(ii)\",\n            \"question\": \"(0, 3) for 3x - 2y = 6\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iii)\",\n            \"question\": \"(3, 0) for 3x - 2y = 6\",\n            \"answer\": \"No\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(iv)\",\n            \"question\": \"(0, -3) for 3x - 2y = 6\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(v)\",\n            \"question\": \"(-2, -6) for 3x - 2y = 6\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"4.(vi)\",\n            \"question\": \"(4, 3) for 3x - 2y = 6\",\n            \"answer\": \"Yes\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(i)\",\n            \"question\": \"Find the value of k if (1, 2) is a solution of 3x + 2y = k\",\n            \"answer\": \"7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"5.(ii)\",\n            \"question\": \"Find the value of k if (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"answer\": \"-7\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        }\n    ],\n    \"quality_flags\": [\n        \"Check final variable name in Example 3 solution on page 1: textbook writes y instead of x in the last step.\",\n        \"Check formatting in Ex 4.1 question 1 (ix) on page 3: expression contains two equals signs in source.\",\n        \"Check Example 3 (ii) text on page 4: source question says x = -2, but solution writes x = 2.\",\n        \"Check Answer 2 (iii) on page 5: source has 12000 instead of 1200 as in statement.\"\n    ]\n}', '{\n    \"source\": {\n        \"board\": \"Board of Secondary Education\",\n        \"board_version\": \"BOSEM 2026-2027\",\n        \"class\": \"Class IX\",\n        \"subject\": \"Mathematics\",\n        \"textbook\": \"Mathematics Class IX\",\n        \"chapter_number\": \"Chapter 4\",\n        \"chapter_title\": \"Linear equations in two variables\"\n    },\n    \"pages\": [\n        {\n            \"page_number\": 1,\n            \"text\": \"CHAPTER\\n4\\nLINEAR EQUATIONS IN TWO VARIABLES\\n\\n4.1 Introduction\\nYou have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{5} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation).\\n\\nExample 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\\n\\nExample 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\\n\\nExample 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"page_number\": 2,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 71\\n\\n4.2 Linear Equations in Two Variables\\nLet us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables.\\n\\nThus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\\n\\nThe general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\\n\\nIf either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\\n\\n4.3 Solution of a Linear Equation in Two Variables\\nYou have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10.\\n\\nThis solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\\n\\nYou have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 3,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 73\\n\\nSimilarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\\n\\n(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e., y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\\n\\n(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2).\\n\\nEXERCISE 4.1\\n1. Solve the following linear equations in one variable :\\n(i) \\\\frac{x}{3} = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\\n(ix) \\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\\n\\n2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\",\n            \"quality_flags\": [\n                \"Check formatting in Ex 4.1 question 1 (ix): expression contains two equals signs in source.\"\n            ]\n        },\n        {\n            \"page_number\": 4,\n            \"text\": \"MATHEMATICS FOR CLASS IX 72\\nin two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\\n\\nExample 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\\n\\nExample 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\\n\\nExample 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\\n\\nExample 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"page_number\": 5,\n            \"text\": \"74 MATHEMATICS FOR CLASS IX\\n(iii) Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\\n\\n3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\\n\\n4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\\n\\n5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\\n\\nANSWERS\\n1. (i) -6\\n(ii) 3\\n(iii) 1\\n(iv) 4\\n(v) 13\\n(vi) 4\\n(vii) \\\\frac{3}{2}\\n(viii) 12\\n(ix) 1\\n(x) 7\\n2. (i) x - 8y = 0\\n(ii) x - y = 5\\n(iii) 2x + 3y = 12000\\n(iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\\n(ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, \\\\frac{5}{2}), (1, \\\\frac{5}{2}), (2, \\\\frac{5}{2}), (3, \\\\frac{5}{2})\\n4. (i) Yes\\n(ii) No\\n(iii) No\\n(iv) Yes\\n(v) Yes\\n(vi) Yes\\n5. (i) 7\\n(ii) -7\",\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"page_number\": 6,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 75\\n\\n4.4 Graph of a Linear Equation in two Variables\\nFrom the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\\n\\nSome of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}.\\n\\nNow, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\\n\\nThus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB};\\n(ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i);\\nand\\n(iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 7,\n            \"text\": \"76 MATHEMATICS FOR CLASS IX\\nSo, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\\n\\nExample 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\\n\\nThe points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 8,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 77\\nRemarks :\\n(i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\\n\\nExample 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\\n\\nThe points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 9,\n            \"text\": \"78 MATHEMATICS FOR CLASS IX\\nRemarks :\\n(i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\\n\\nExample 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\\n\\nExample 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"quality_flags\": []\n        },\n        {\n            \"page_number\": 10,\n            \"text\": \"LINEAR EQUATIONS IN TWO VARIABLES 79\\nSolution :\\nHere the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\\n\\nTo draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"quality_flags\": []\n        }\n    ],\n    \"page_blocks\": [\n        {\n            \"order\": 1,\n            \"block_type\": \"heading\",\n            \"text\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES\",\n            \"title\": \"CHAPTER 4 LINEAR EQUATIONS IN TWO VARIABLES\",\n            \"level\": 1,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 2,\n            \"block_type\": \"heading\",\n            \"text\": \"4.1 Introduction\",\n            \"title\": \"4.1 Introduction\",\n            \"level\": 2,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 3,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have studied linear equations in one variable in the previous classes. Recall that a linear equation in one variable is an equation involving only linear polynomials in one variable. Thus, equations of the form ax = b, ax + b = c, ax + b = cx + d (where a ≠ 0, b, c, d are constants) are linear equations in one variable. For example, x + 2 = 0, 2x - \\\\sqrt{5} = 0, 5x + 3 = 3x - 5, \\\\frac{x}{2} - 3 = \\\\frac{x}{3} + 3 etc. are linear equations in one variable. You also know that such equations have a unique (i.e. one and only one) solution. Now, let us see some examples of solving linear equations in one variable (i.e. finding the value of the variable satisfying the equation).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 4,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 5,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 6,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 1,\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"order\": 7,\n            \"block_type\": \"heading\",\n            \"text\": \"4.2 Linear Equations in Two Variables\",\n            \"title\": \"4.2 Linear Equations in Two Variables\",\n            \"level\": 2,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 8,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Let us now consider the statement \\\"The sum of two numbers is 10\\\". If we denote the first number by x and the second number by y, then the statement can be expressed as \\\"x + y = 10\\\". This is a linear equation in two variables (x and y). Likewise 3x + y = -5, 2x - y = 4, -4x + 3y = 9, \\\\frac{x}{3} + \\\\frac{y}{4} = 1 etc. are all linear equations in two variables.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 9,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Thus, a linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 10,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 11,\n            \"block_type\": \"paragraph\",\n            \"text\": \"If either a = 0 or b = 0, the equation ax + by + c = 0 is no more a linear equation in two variables in its most general form. But in some special circumstances, either a or b is granted to be zero. For example, the equation 3x + 2 = 0 can be written in the general form as 3x + 0.y + 2 = 0.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 12,\n            \"block_type\": \"heading\",\n            \"text\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"title\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"level\": 2,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 13,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have already known that every linear equation in one variable has a unique solution. What can you say about the solution of a linear equation in two variables? If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation. Let us consider the equation 3x + y = 10. Here, x = 3 and y = 1 constitute a solution of this equation because the equation holds when x = 3 and y = 1, for 3x + y = 3 \\\\times 3 + 1 = 10.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 14,\n            \"block_type\": \"paragraph\",\n            \"text\": \"This solution is written as an ordered pair (3, 1). In such an ordered pair the first component invariably represents a value of x and the second, the corresponding value of y. Similarly, the ordered pair (2, 4) is also a solution of the equation 3x + y = 10. But (2, 5) is not a solution of this equation, because on putting x = 2 and y = 5, we get 3x + y = 6 + 5 = 11 ≠ 10.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 15,\n            \"block_type\": \"paragraph\",\n            \"text\": \"You have already seen two solutions of the equation 3x + y = 10 viz. (3, 1) and (2, 4). You can also verify that (0, 10) is also another solution of the equation. In fact, we can get many solutions of the equation by assigning different values to x (or y) in the equation and finding the corresponding value of the other. For example, if we take x = 1 in the equation, we get 3 + y = 10 i.e. y = 7. So, (1, 7) is another solution of the equation 3x + y = 10. Again, taking x = -2, we get y = 16 so that (-2, 16) is also another solution of the equation. Thus, there is no end to different solutions of a linear equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 16,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Similarly, taking y = 0, the given equation reduces to 2x = 6, which gives x = 3. So, (3, 0) is also a solution of the given equation.\\nAgain, taking x = 6, we get 12 + 3y = 6 i.e. y = -2. Therefore, (6, -2) is also another solution of the equation.\\nHence, three solutions of the equation 2x + 3y = 6 can be given as (0, 2), (3, 0) and (6, -2).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 17,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(ii) Taking x = 0, the equation 3x + 4y = 0 reduces to 4y = 0 i.e., y = 0. So, (0, 0) is a solution of the equation 3x + 4y = 0.\\nAgain, taking x = 4, we get 12 + 4y = 0 i.e., y = -3. Therefore, (4, -3) is a solution of the given equation.\\nSimilarly, taking y = 3, we get 3x + 12 = 0 i.e., x = -4. So, (-4, 3) is also another solution of the equation.\\nHence, three solutions of the given equation are (0, 0), (4, -3) and (-4, 3).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 18,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(iii) Writing the equation 2x + 5 = 0 as 2x + 0.y + 5 = 0, we obtain x = -\\\\frac{5}{2} for any value of y. Hence any three solutions of the given equation are (-\\\\frac{5}{2}, 0), (-\\\\frac{5}{2}, 1) and (-\\\\frac{5}{2}, 2).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 19,\n            \"block_type\": \"heading\",\n            \"text\": \"EXERCISE 4.1\",\n            \"title\": \"EXERCISE 4.1\",\n            \"level\": 1,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 20,\n            \"block_type\": \"question\",\n            \"text\": \"1. Solve the following linear equations in one variable :\\n(i) \\\\frac{x}{3} = -2\\n(ii) 4x + 3 = 15\\n(iii) 3x + 2 = x + 4\\n(iv) 9x - 4 = 32\\n(v) 3y + 5(2 - y) = -16\\n(vi) 13t - 4(t + 8) - 4 = 0\\n(vii) (x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\\n(viii) \\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\\n(ix) \\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\\n(x) 2(x - 15) = 5(x - 11) + 4\",\n            \"title\": \"1\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": [\n                \"Check formatting in Ex 4.1 question 1 (ix): expression contains two equals signs in source.\"\n            ]\n        },\n        {\n            \"order\": 21,\n            \"block_type\": \"question\",\n            \"text\": \"2. Write linear equations in two variables to represent the following statements :\\n(i) The cost of a pen is eight times that of a pencil.\\n(ii) The difference of two numbers is 5.\",\n            \"title\": \"2\",\n            \"level\": 0,\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 22,\n            \"block_type\": \"paragraph\",\n            \"text\": \"in two variables. In other words, a linear equation in two variables has infinitely many solutions. However, an arbitrary ordered pair need not be a solution of the equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 23,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 24,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 25,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"order\": 26,\n            \"block_type\": \"example\",\n            \"text\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"title\": \"Example 4\",\n            \"level\": 0,\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 27,\n            \"block_type\": \"paragraph\",\n            \"text\": \"(iii) Two tables and three chairs cost ₹ 1200.\\n(iv) Two numbers are in the ratio 2 : 3.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 28,\n            \"block_type\": \"question\",\n            \"text\": \"3. Find four different solutions for each of the following equations in two variables:\\n(i) x = 3y\\n(ii) 4x + 3y = 12\\n(iii) x + 2y = 6\\n(iv) 5x + 2y = 0\\n(v) 3x + 4 = 0\\n(vi) 2y - 5 = 0\",\n            \"title\": \"3\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 29,\n            \"block_type\": \"question\",\n            \"text\": \"4. Check which of the following are solutions of the equation 3x - 2y = 6 and which are not :\\n(i) (2, 0)\\n(ii) (0, 3)\\n(iii) (3, 0)\\n(iv) (0, -3)\\n(v) (-2, -6)\\n(vi) (4, 3)\",\n            \"title\": \"4\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 30,\n            \"block_type\": \"question\",\n            \"text\": \"5. Find the value of k if\\n(i) (1, 2) is a solution of 3x + 2y = k\\n(ii) (2, -3) is a solution of kx - 3y + 5 = 0.\",\n            \"title\": \"5\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 31,\n            \"block_type\": \"answer\",\n            \"text\": \"ANSWERS\\n1. (i) -6\\n(ii) 3\\n(iii) 1\\n(iv) 4\\n(v) 13\\n(vi) 4\\n(vii) \\\\frac{3}{2}\\n(viii) 12\\n(ix) 1\\n(x) 7\\n2. (i) x - 8y = 0\\n(ii) x - y = 5\\n(iii) 2x + 3y = 12000\\n(iv) 3x - 2y = 0\\n3. (i) (0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\\n(ii) (0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\\n(iii) (0, 3), (6, 0), (2, 2), (-2, 4)\\n(iv) (0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\\n(v) (-4, 0), (-4, 1), (-4, 2), (-4, 3)\\n(vi) (0, \\\\frac{5}{2}), (1, \\\\frac{5}{2}), (2, \\\\frac{5}{2}), (3, \\\\frac{5}{2})\\n4. (i) Yes\\n(ii) No\\n(iii) No\\n(iv) Yes\\n(v) Yes\\n(vi) Yes\\n5. (i) 7\\n(ii) -7\",\n            \"title\": \"ANSWERS\",\n            \"level\": 0,\n            \"page_number\": 5,\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"order\": 32,\n            \"block_type\": \"heading\",\n            \"text\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"title\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"level\": 2,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 33,\n            \"block_type\": \"paragraph\",\n            \"text\": \"From the previous article you know that a linear equation in two variables has infinitely many solutions and you have obtained some of these solutions algebraically so far. Now, let us look at their geometrical representation. Consider the following equation :\\n2x + 3y = 12 ... (i)\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 34,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Some of the solutions of this equation are (0, 4), (6, 0), (3, 2), (-3, 6). The points represented by these ordered pairs are plotted in the cartesian plane. Joining any two of these points we obtain a straight line \\\\overline{AB} (Fig. 4.1). Also we see that the other two points lie on the line \\\\overline{AB}.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 35,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Now, let us take a point on this line, say P. On finding the co-ordinates of P, we find the ordered pair (9, -2). We see that (9, -2) is a solution of the equation for x = 9 and y = -2 satisfy the equation. Similarly, the co-ordinates of any other point on the straight line \\\\overline{AB} may be shown to satisfy the equation. But the co-ordinates of a point which is outside the line \\\\overline{AB} do not satisfy the equation. For example, the point Q(2, 1) is not on the line \\\\overline{AB} and its co-ordinates do not satisfy equation (i) as such (2, 1) is not a solution of this equation.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 36,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Thus, we observe that\\n(i) every point whose co-ordinates satisfy equation (i) lies on the line \\\\overline{AB};\\n(ii) the co-ordinates of every point on the line \\\\overline{AB} constitute a solution of equation (i);\\nand\\n(iii) the co-ordinates of any point which does not lie on the line \\\\overline{AB} do not constitute a solution of equation (i).\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 6,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 37,\n            \"block_type\": \"paragraph\",\n            \"text\": \"So, the linear equation (i) is geometrically represented by the line \\\\overline{AB}. This line is called the graph of the linear equation. Thus, we conclude that the graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation. To obtain the graph of a linear equation in two variables, it is enough to plot two points corresponding to two solutions of the equation and draw a line through them. However, it is better to plot at least three such points so that you can immediately check the correctness of the graph.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 38,\n            \"block_type\": \"example\",\n            \"text\": \"Example 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as\\nx + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"title\": \"Example 1\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 39,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The points represented by the above ordered pairs are plotted in the cartesian plane. Joining these points we get a straight line \\\\overline{AB} (Fig. 4.2). The line \\\\overline{AB} thus obtained is the graph of the equation x = 5.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 40,\n            \"block_type\": \"note\",\n            \"text\": \"Remarks :\\n(i) The graph of the equation x = c, where c is a constant, is a straight line parallel to the Y-axis and cuts the X-axis at (c, 0). The abscissa of any point lying on this line is c.\\n(ii) The graph of x = 0 is the Y-axis.\",\n            \"title\": \"Remarks\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 41,\n            \"block_type\": \"example\",\n            \"text\": \"Example 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"title\": \"Example 2\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 42,\n            \"block_type\": \"paragraph\",\n            \"text\": \"The points represented by the above ordered pairs are plotted. Joining these points we get a straight line \\\\overline{AB} as shown in Fig. 4.3. The straight line \\\\overline{AB} is the graph of the equation y = 4.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 43,\n            \"block_type\": \"note\",\n            \"text\": \"Remarks :\\n(i) The graph of the equation y = c, where c is a constant, is a straight line parallel to the X-axis. It cuts the Y-axis at the point (0, c). The ordinate of any point on this line is c.\\n(ii) The graph of y = 0 is the X-axis.\",\n            \"title\": \"Remarks\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 44,\n            \"block_type\": \"example\",\n            \"text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"title\": \"Example 3\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 45,\n            \"block_type\": \"example\",\n            \"text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"title\": \"Example 4\",\n            \"level\": 0,\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 46,\n            \"block_type\": \"paragraph\",\n            \"text\": \"Here the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 10,\n            \"quality_flags\": []\n        },\n        {\n            \"order\": 47,\n            \"block_type\": \"paragraph\",\n            \"text\": \"To draw the graph of this equation, we take some of the ordered pairs satisfying the equation as given below :\",\n            \"title\": \"\",\n            \"level\": 0,\n            \"page_number\": 10,\n            \"quality_flags\": []\n        }\n    ],\n    \"headings\": [\n        {\n            \"title\": \"4.1 Introduction\",\n            \"level\": 2,\n            \"canonical_text\": \"4.1 Introduction\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.2 Linear Equations in Two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.2 Linear Equations in Two Variables\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.3 Solution of a Linear Equation in Two Variables\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"EXERCISE 4.1\",\n            \"level\": 1,\n            \"canonical_text\": \"EXERCISE 4.1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"level\": 2,\n            \"canonical_text\": \"4.4 Graph of a Linear Equation in two Variables\",\n            \"page_number\": 6,\n            \"quality_flags\": []\n        }\n    ],\n    \"concepts\": [\n        {\n            \"name\": \"Linear equation in one variable\",\n            \"canonical_text\": \"A linear equation in one variable is an equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Linear equation in two variables\",\n            \"canonical_text\": \"A linear polynomial in two variables equated to zero gives a linear equation in two variables. It is also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Solution of a linear equation in two variables\",\n            \"canonical_text\": \"If the two variables be x and y, then a pair of values, one for x and one for y which satisfy the equation is called a solution of the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"name\": \"Graph of a linear equation\",\n            \"canonical_text\": \"The graph of a linear equation is a straight line whose points make up the aggregate of solutions, of the equation.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        }\n    ],\n    \"definitions\": [\n        {\n            \"term\": \"Linear equation in one variable\",\n            \"definition\": \"An equation involving only linear polynomials in one variable.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"term\": \"Linear equation in two variables\",\n            \"definition\": \"A linear polynomial in two variables equated to zero, also called a first degree equation in two variables.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        },\n        {\n            \"term\": \"Solution of a linear equation in two variables\",\n            \"definition\": \"A pair of values, one for x and one for y which satisfy the equation.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"formulas\": [\n        {\n            \"expression\": \"ax + by + c = 0\",\n            \"canonical_text\": \"The general form of a linear equation in two variables is ax + by + c = 0, where a, b, c are constants and a, b are both non-zeroes.\",\n            \"page_number\": 2,\n            \"quality_flags\": []\n        }\n    ],\n    \"examples\": [\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"Solve 4x + 3 = 15\",\n            \"solution\": \"4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"canonical_text\": \"Example 1 : Solve 4x + 3 = 15\\nSolution :\\n4x + 3 = 15\\nor\\n4x = 15 - 3\\n(by transposition)\\nor\\n4x = 12\\n∴\\nx = \\\\frac{12}{4} = 3.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Solve 4x + 3 = 2x + 5\",\n            \"solution\": \"4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"canonical_text\": \"Example 2 : Solve 4x + 3 = 2x + 5\\nSolution :\\n4x + 3 = 2x + 5\\nor\\n4x - 2x = 5 - 3\\n(by transposition)\\nor\\n2x = 2\\n∴\\nx = 1.\",\n            \"page_number\": 1,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\",\n            \"solution\": \"\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"canonical_text\": \"Example 3 : Solve \\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\n\'Solution :\\n\\\\frac{x}{3} + 1 = \\\\frac{x}{4} - 2\\nor\\n\\\\frac{x}{3} - \\\\frac{x}{4} = -2 - 1\\n(by transposition)\\nor\\n\\\\frac{x}{12} = -3\\n∴\\ny = -3 \\\\times 12 = -36.\",\n            \"page_number\": 1,\n            \"quality_flags\": [\n                \"Check final variable name in Example 3 solution: textbook writes y instead of x in the last step.\"\n            ]\n        },\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\",\n            \"solution\": \"Let the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"canonical_text\": \"Example 1 : The cost of a notebook is twice that of a pen. Write a linear equation to represent this statement.\\nSolution :\\nLet the cost of a notebook be x and that of a pen be y.\\nThen we have,\\nx = 2y\\nor\\nx - 2y = 0.\\nThis is the linear equation which represents the given statement.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\",\n            \"solution\": \"(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"canonical_text\": \"Example 2 : Write each of the following equations in the form ax + by + c = 0 (a > 0) and indicate the values of a, b and c in each case :\\n(i) 3x - 4y = 5, (ii) x + 5 = 2y and (iii) 3x = y.\\nSolution :\\n(i) The equation 3x - 4y = 5 can be written as 3x - 4y - 5 = 0, which is of the form ax + by + c = 0. Here a = 3, b = -4 and c = -5.\\n(ii) The equation x + 5 = 2y can be written as x - 2y + 5 = 0, which is of the form ax + by + c = 0. Here a = 1, b = -2 and c = 5.\\n(iii) The equation 3x = y can be written as 3x - y + 0 = 0, which is of the form ax + by + c = 0, where a = 3, b = -1 and c = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\",\n            \"solution\": \"(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"canonical_text\": \"Example 3 : Write each of the following as an equation in two variables :\\n(i) 4x = 3\\n(ii) x = -2\\n(iii) 2y = 5\\nSolution :\\n(i) 4x = 3 can be written as 4x + 0.y = 3 or 4x + 0.y - 3 = 0.\\n(ii) x = 2 can be written as x + 0.y - 2 = 0.\\n(iii) 2y = 5 can be written as 0.x + 2y - 5 = 0.\",\n            \"page_number\": 4,\n            \"quality_flags\": [\n                \"Check Example 3 (ii) text: source question says x = -2, but solution writes x = 2.\"\n            ]\n        },\n        {\n            \"title\": \"Example 4\",\n            \"question\": \"Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\",\n            \"solution\": \"(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"canonical_text\": \"Example 4 : Find any three different solutions for each of the following equations :\\n(i) 2x + 3y = 6\\n(ii) 3x + 4y = 0\\n(iii) 2x + 5 = 0.\\nSolution :\\n(i) Taking x = 0, the equation 2x + 3y = 6 reduces to 3y = 6, which gives y = 2. Therefore, (0, 2) is a solution of the equation 2x + 3y = 6.\",\n            \"page_number\": 4,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 1\",\n            \"question\": \"Draw the graph of x = 5.\",\n            \"solution\": \"x = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i) which is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below : (5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"canonical_text\": \"Example 1 : Draw the graph of x = 5.\\nSolution :\\nx = 5 is a linear equation in one variable. However, it can be written as x + 0.y = 5 ... (i)\\nwhich is a linear equation in two variables. Some of the ordered pairs which satisfy equation (i) are given below :\\n(5, 0), (5, 2), (5, 5), (5, -3) etc.\",\n            \"page_number\": 7,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 2\",\n            \"question\": \"Draw the graph of y = 4.\",\n            \"solution\": \"y = 4 is a linear equation in one variable. Writing this equation in the form 0.x + y = 4 we have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below : (0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"canonical_text\": \"Example 2 : Draw the graph of y = 4.\\nSolution :\\ny = 4 is a linear equation in one variable.\\nWriting this equation in the form\\n0.x + y = 4\\nwe have a linear equation in two variables x and y. Some of the ordered pairs satisfying the above equation are given below :\\n(0, 4), (2, 4), (5, 4), (-3, 4) etc.\",\n            \"page_number\": 8,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 3\",\n            \"question\": \"Draw the graph of 3x + 5y = 15.\",\n            \"solution\": \"3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4.\",\n            \"canonical_text\": \"Example 3 : Draw the graph of 3x + 5y = 15.\\nSolution :\\n3x + 5y = 15 is a linear equation in two variables x and y. Some of the ordered pairs satisfying this equation are (0, 3), (5, 0), (10, -3), (-5, 6) etc. Plotting the points represented by these ordered pairs and joining them we get a straight line \\\\overline{AB} as shown in Fig. 4.4. The straight line \\\\overline{AB} is the graph of the equation 3x + 5y = 15.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        },\n        {\n            \"title\": \"Example 4\",\n            \"question\": \"If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\",\n            \"solution\": \"Let x be the distance travelled and y be the work done. y = kx. For k = 2, y = 2x.\",\n            \"canonical_text\": \"Example 4 : If the work done by a constant force acting on a body is directly proportional to the distance travelled by the body, the constant of proportionality being the constant force, express this in the form of an equation in two variables and draw the graph of the same by taking the constant force as 2 units. Also read from the graph the work done when the distance travelled by the body is 5 units.\\nSolution :\\nHere the variables involved are distance and work. Let x be the distance travelled by the body and the work done by the body be y units. It is given that y ∝ x. If k be the constant force acting on the body (which is also the constant of proportionality), then\\ny = kx,\\nwhich is the linear equation representing the given statement.\\nIf k = 2 units, the above equation becomes\\ny = 2x.\",\n            \"page_number\": 9,\n            \"quality_flags\": []\n        }\n    ],\n    \"figures\": [\n        {\n            \"figure_number\": \"Fig. 4.1\",\n            \"title\": \"Cartesian plane with straight line AB for 2x + 3y = 12\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing line AB passing through points A(-3, 6), (0, 4), Q(2, 1), (3, 2), (6, 0), P(9, -2), B.\",\n            \"equations\": [\n                \"2x + 3y = 12\"\n            ],\n            \"labelled_points\": [\n                \"A(-3, 6)\",\n                \"(0, 4)\",\n                \"Q(2, 1)\",\n                \"(3, 2)\",\n                \"\\\\mathbf{Q}(2, 1)\",\n                \"(6, 0)\",\n                \"P(9, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 6,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.2\",\n            \"title\": \"Graph of x = 5\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing vertical line AB representing x = 5.\",\n            \"equations\": [\n                \"x = 5\",\n                \"x + 0.y = 5\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 5)\",\n                \"(5, 2)\",\n                \"(5, 0)\",\n                \"(5, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 7,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.3\",\n            \"title\": \"Graph of y = 4\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing horizontal line AB representing y = 4.\",\n            \"equations\": [\n                \"y = 4\",\n                \"0.x + y = 4\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-3, 4)\",\n                \"(0, 4)\",\n                \"(2, 4)\",\n                \"(5, 4)\",\n                \"B\"\n            ],\n            \"page_number\": 8,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.4\",\n            \"title\": \"Graph of 3x + 5y = 15\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing straight line AB for 3x + 5y = 15.\",\n            \"equations\": [\n                \"3x + 5y = 15\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(-5, 6)\",\n                \"(0, 3)\",\n                \"(5, 0)\",\n                \"(10, -3)\",\n                \"B\"\n            ],\n            \"page_number\": 9,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        },\n        {\n            \"figure_number\": \"Fig. 4.5\",\n            \"title\": \"Graph of y = 2x\",\n            \"type\": \"Cartesian graph\",\n            \"description\": \"Cartesian plane showing straight line AB for y = 2x.\",\n            \"equations\": [\n                \"y = 2x\"\n            ],\n            \"labelled_points\": [\n                \"A\",\n                \"(5, 10)\",\n                \"(4, 8)\",\n                \"(2, 4)\",\n                \"(0, 0)\",\n                \"(-1, -2)\",\n                \"B\"\n            ],\n            \"page_number\": 10,\n            \"image_path\": \"\",\n            \"quality_flags\": []\n        }\n    ],\n    \"tables\": [],\n    \"questions\": [\n        {\n            \"question_number\": \"1.(i)\",\n            \"question\": \"\\\\frac{x}{3} = -2\",\n            \"answer\": \"-6\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ii)\",\n            \"question\": \"4x + 3 = 15\",\n            \"answer\": \"3\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iii)\",\n            \"question\": \"3x + 2 = x + 4\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(iv)\",\n            \"question\": \"9x - 4 = 32\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(v)\",\n            \"question\": \"3y + 5(2 - y) = -16\",\n            \"answer\": \"13\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vi)\",\n            \"question\": \"13t - 4(t + 8) - 4 = 0\",\n            \"answer\": \"4\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(vii)\",\n            \"question\": \"(x - 2)(x - 3) + 2(x - 1)(x - 3) = 3(x - 1)(x - 2)\",\n            \"answer\": \"\\\\frac{3}{2}\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(viii)\",\n            \"question\": \"\\\\frac{x}{2} + 5 = \\\\frac{x}{3} + 7\",\n            \"answer\": \"12\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(ix)\",\n            \"question\": \"\\\\frac{x + 2}{3} = \\\\frac{x - 1}{2} = 1\",\n            \"answer\": \"1\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"1.(x)\",\n            \"question\": \"2(x - 15) = 5(x - 11) + 4\",\n            \"answer\": \"7\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(i)\",\n            \"question\": \"The cost of a pen is eight times that of a pencil.\",\n            \"answer\": \"x - 8y = 0\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(ii)\",\n            \"question\": \"The difference of two numbers is 5.\",\n            \"answer\": \"x - y = 5\",\n            \"page_number\": 3,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"2.(iii)\",\n            \"question\": \"Two tables and three chairs cost ₹ 1200.\",\n            \"answer\": \"2x + 3y = 12000\",\n            \"page_number\": 5,\n            \"quality_flags\": [\n                \"Check Answer 2 (iii): source has 12000 instead of 1200 as in statement.\"\n            ]\n        },\n        {\n            \"question_number\": \"2.(iv)\",\n            \"question\": \"Two numbers are in the ratio 2 : 3.\",\n            \"answer\": \"3x - 2y = 0\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(i)\",\n            \"question\": \"x = 3y\",\n            \"answer\": \"(0, 0), (3, 1), (-6, -2), (1, \\\\frac{1}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(ii)\",\n            \"question\": \"4x + 3y = 12\",\n            \"answer\": \"(0, 4), (3, 0), (-3, 8), (1, \\\\frac{8}{3})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iii)\",\n            \"question\": \"x + 2y = 6\",\n            \"answer\": \"(0, 3), (6, 0), (2, 2), (-2, 4)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(iv)\",\n            \"question\": \"5x + 2y = 0\",\n            \"answer\": \"(0, 0), (2, -5), (-2, 5), (1, -\\\\frac{5}{2})\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"question_number\": \"3.(v)\",\n            \"question\": \"3x + 4 = 0\",\n            \"answer\": \"(-4, 0), (-4, 1), (-4, 2), (-4, 3)\",\n            \"page_number\": 5,\n            \"quality_flags\": []\n        },\n        {\n            \"q